    /**
    * @brief ind = min(abs(x(:))
    find the minimal absolute value of x and its position index ind
    r = x[ind], not abs(x[ind])
    */
    template <typename T>  
    void minAbsolute(const hoNDArray<T>& x, T& r, size_t& ind);

