    template <typename T> void sqrt(const hoNDArray<T>& x, hoNDArray<T>& r) {
        using std::sqrt;
        if (r.get_number_of_elements() != x.get_number_of_elements()) {
            r.create(x.dimensions());
        }

        size_t N    = x.get_number_of_elements();
        const T* pX = x.begin();
        T* pR       = r.begin();

        long long n;
        for (n = 0; n < (long long)N; n++) {
            pR[n] = sqrt(pX[n]);
        }
    }

